import{_ as t,H as p,f as a,i as o}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"每周一起背10句 | week 07","description":"","frontmatter":{},"headers":[],"relativePath":"互联网人的英语私教课/每周一起背10句-week07.md","filePath":"互联网人的英语私教课/每周一起背10句-week07.md","lastUpdated":1779817970000}'),s={name:"互联网人的英语私教课/每周一起背10句-week07.md"};function i(r,e,n,h,l,c){return p(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="每周一起背10句-week-07" tabindex="-1">每周一起背10句 | week 07 <a class="header-anchor" href="#每周一起背10句-week-07" aria-label="Permalink to &quot;每周一起背10句 | week 07&quot;">​</a></h1><p>你好，我是英语专栏的编辑阿锦，欢迎来到第7期的“每周一起背10句”。</p><p>本周我们继续阅读第四篇语料。读了这么久的句子，本周我们又开始学单词了。单词是我们学英语的过程中，一直不断要学习的东西。很多人在学单词的时候，会遇到查词典的问题。因此，陈老师给我们推荐了很多本不错的词典，也给我们讲解了查词典的具体方法，不知道你都学会了吗？</p><p>好了，今天的10个句子都是关于本周的几个重点单词的，我们一起来看看吧！</p><hr><p>例句1：Ill health often goes with poverty.</p><p>翻译：疾病往往伴随贫困而来。</p><p>例句2：What are the responsibilities that goes with becoming a father?</p><p>翻译：成为父亲之后要承担哪些责任？</p><p>例句3：This wine goes particularly well with seafood.</p><p>翻译：这款葡萄酒特别适合搭配海鲜。</p><p>例句4：The music doesn’t go with the mood of the film.</p><p>翻译：配乐和这部电影的基调不搭。</p><p>例句5：Many employees complain that their bosses are poor communicators and bad at giving clear instructions.</p><p>翻译：很多员工抱怨他们老板不善于沟通，无法下达明确的指令。</p><p>例句6：He emphasized that managers had to be more communicative with their staff.</p><p>翻译：他强调，管理人员要加强与员工的沟通交流。</p><p>例句7：The test evaluates students’ communicative skills.</p><p>翻译：该项测试主要考核学生的沟通能力。</p><p>例句8：My daughter is very difficult, uncommunicative and moody.</p><p>翻译：我女儿很难相处，不愿跟人交流，又非常情绪化。</p><p>例句9：The bill drew support from across the political spectrum.</p><p>翻译：该项法案赢得了各政治派别的支持。</p><p>例句10：The two articles here represent opposite ends of the spectrum.</p><p>翻译：这两篇文章代表着截然不同的两派观点。</p>',25)])])}const _=t(s,[["render",i]]);export{d as __pageData,_ as default};
